Lemma ENOMEM_in_mprotect_errnos : In ENOMEM mprotect_errnos.
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "S00!3,6!3+E+Z'g;'g;!3'fB+Z'g;!1,^8+Z!2,@+Z'g;").
